// Chile tiene DST: UTC-3 en verano, UTC-4 en invierno (abril-septiembre)
// Para cubrir AMBOS casos sin hardcodear, usamos un rango amplio en UTC
// Medianoche Santiago más temprana = UTC+4h, más tardía = UTC+3h
// Cubrimos T03:00Z a T04:00Z siguiente día = siempre captura el día completo
const date = $input.first().json.query?.date || new Date().toISOString().split('T')[0];
const [y, m, d] = date.split('-').map(Number);
const timeMin = new Date(Date.UTC(y, m-1, d, 3, 0, 0)).toISOString();     // 00:00 Santiago UTC-3
const timeMax = new Date(Date.UTC(y, m-1, d+1, 4, 0, 0)).toISOString();   // 00:00 Santiago UTC-4 siguiente día
return [{ json: { date, timeMin, timeMax } }];

// Slots definidos en la página (deben coincidir con el frontend)
const SLOT_STARTS = ['09:00', '10:30', '12:00', '15:00', '16:30', '18:00'];
const busy = [];

// Fecha que se consultó — para no bloquear otros días accidentalmente
const queriedDate = $('🔧 Armar Rango del Día').first().json.date;

const items = $input.all();
for (const item of items) {
  const ev = item.json;
  if (!ev || !ev.start) continue;

  const startDT = ev.start.dateTime || ev.start.date;
  if (!startDT) continue;

  // Google Calendar devuelve el dateTime con la hora local incluida
  // Ej: "2026-04-13T09:00:00-04:00" — tomamos la hora directamente sin conversión UTC
  // Esto funciona independiente de si Chile está en UTC-3 o UTC-4
  let localDate, hhmm;
  if (startDT.length >= 19 && (startDT[19] === '+' || startDT[19] === '-' || startDT[19] === 'Z')) {
    // Tiene offset — extraer fecha y hora de la parte local directamente
    localDate = startDT.substring(0, 10);  // "2026-04-13"
    hhmm      = startDT.substring(11, 16); // "09:00"
  } else {
    // Sin offset (all-day o date-only)
    localDate = startDT.substring(0, 10);
    hhmm      = startDT.length >= 16 ? startDT.substring(11, 16) : '00:00';
  }

  if (localDate !== queriedDate) continue;
  if (SLOT_STARTS.includes(hhmm) && !busy.includes(hhmm)) {
    busy.push(hhmm);
  }
}

return [{ json: { busy } }];
